INSERT INTO lessons VALUES('P2A-U04-L1',1,'action-courses-v1',2,'A',4,'衣帽架的小标签','{"id":"P2A-U04-L1","unitId":"P2A-U04","grade":2,"term":"A","unitNumber":4,"unitLesson":1,"order":13,"title":"衣帽架的小标签","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"action-courses-v1","unitTitle":"整理小能手","cards":[{"title":"衣帽架的小标签","rule":"my是说话人的，your是听话人的；本文明确用he称呼的人配his，用she称呼的人配her。先找物品属于谁，再选词。","example":"This is his striped scarf.","translation":"这是他的条纹围巾。"},{"title":"衣帽架的小标签","rule":"my是说话人的，your是听话人的；本文明确用he称呼的人配his，用she称呼的人配her。先找物品属于谁，再选词。","example":"These are her silver shoes.","translation":"这是她的银色鞋子。"},{"title":"衣帽架的小标签","rule":"my是说话人的，your是听话人的；本文明确用he称呼的人配his，用she称呼的人配her。先找物品属于谁，再选词。","example":"That is your warm jacket.","translation":"那是你的保暖夹克。"}],"vocabulary":[{"word":"coat","meaning":"外套"},{"word":"scarf","meaning":"围巾"},{"word":"gloves","meaning":"手套"},{"word":"tidy","meaning":"整齐的"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["grammar.possession"],"itemCount":9}');
