INSERT INTO lessons VALUES('P3A-U04-L1',1,'action-courses-v1',3,'A',4,'操场此刻在发生什么','{"id":"P3A-U04-L1","unitId":"P3A-U04","grade":3,"term":"A","unitNumber":4,"unitLesson":1,"order":13,"title":"操场此刻在发生什么","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"action-courses-v1","unitTitle":"忙碌的现在","cards":[{"title":"操场此刻在发生什么","rule":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","example":"Eva is planting seeds beside a wall.","translation":"Eva正在墙边种种子。"},{"title":"操场此刻在发生什么","rule":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","example":"Our friends are polishing a model plane.","translation":"朋友们正在擦一架模型飞机。"},{"title":"操场此刻在发生什么","rule":"这些情景说此刻正在进行的动作，用am/is/are加动词-ing。I配am，单数人物配is，you/we/they及复数人物配are；-ing拼写需按具体词核对，不把双写套到所有词。","example":"I am hanging a paper lantern.","translation":"我正在挂一盏纸灯笼。"}],"vocabulary":[{"word":"carry","meaning":"搬、提"},{"word":"rope","meaning":"绳子"},{"word":"glue","meaning":"胶水"},{"word":"borrow","meaning":"借入"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.present-continuous","forms.ing"],"itemCount":9}');
