INSERT INTO lessons VALUES('P5A-U04-L1',1,'action-courses-v1',5,'A',4,'铃声响起的那一刻','{"id":"P5A-U04-L1","unitId":"P5A-U04","grade":5,"term":"A","unitNumber":4,"unitLesson":1,"order":13,"title":"铃声响起的那一刻","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"action-courses-v1","unitTitle":"意外与帮助","cards":[{"title":"铃声响起的那一刻","rule":"本组用过去进行时交代当时正在做的背景，用一般过去时讲发生的事件，再用when连接。不能只看到when就猜时态，要看题目指定的背景与事件意义。","example":"I was polishing a helmet when the coach waved.","translation":"教练挥手时，我正在擦头盔。"},{"title":"铃声响起的那一刻","rule":"本组用过去进行时交代当时正在做的背景，用一般过去时讲发生的事件，再用when连接。不能只看到when就猜时态，要看题目指定的背景与事件意义。","example":"Eva was checking a rope when the guide called.","translation":"向导叫她时，Eva正在检查绳子。"},{"title":"铃声响起的那一刻","rule":"本组用过去进行时交代当时正在做的背景，用一般过去时讲发生的事件，再用when连接。不能只看到when就猜时态，要看题目指定的背景与事件意义。","example":"We were loading a canoe when the horn sounded.","translation":"汽笛响时，我们正在装独木舟。"}],"vocabulary":[{"word":"parcel","meaning":"包裹"},{"word":"spill","meaning":"洒出"},{"word":"equipment","meaning":"器材"},{"word":"neighbour","meaning":"邻居"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-contrast","tense.past-continuous"],"itemCount":9}');
