INSERT INTO lessons VALUES('P5A-U04-L4',1,'action-courses-v1',5,'A',4,'帮助之后说清楚','{"id":"P5A-U04-L4","unitId":"P5A-U04","grade":5,"term":"A","unitNumber":4,"unitLesson":4,"order":16,"title":"帮助之后说清楚","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"action-courses-v1","unitTitle":"意外与帮助","cards":[{"title":"帮助之后说清楚","rule":"本组用过去进行时交代当时正在做的背景，用一般过去时讲发生的事件，再用when连接。不能只看到when就猜时态，要看题目指定的背景与事件意义。","example":"I was polishing a helmet when the coach waved.","translation":"教练挥手时，我正在擦头盔。"},{"title":"帮助之后说清楚","rule":"本组用过去进行时交代当时正在做的背景，用一般过去时讲发生的事件，再用when连接。不能只看到when就猜时态，要看题目指定的背景与事件意义。","example":"Eva was checking a rope when the guide called.","translation":"向导叫她时，Eva正在检查绳子。"},{"title":"帮助之后说清楚","rule":"本组用过去进行时交代当时正在做的背景，用一般过去时讲发生的事件，再用when连接。不能只看到when就猜时态，要看题目指定的背景与事件意义。","example":"We were loading a canoe when the horn sounded.","translation":"汽笛响时，我们正在装独木舟。"}],"vocabulary":[{"word":"parcel","meaning":"包裹"},{"word":"spill","meaning":"洒出"},{"word":"equipment","meaning":"器材"},{"word":"neighbour","meaning":"邻居"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-contrast","tense.past-continuous"],"itemCount":9}');
INSERT INTO lessons VALUES('P6A-U04-L1',1,'action-courses-v1',6,'A',4,'线索藏在背景里','{"id":"P6A-U04-L1","unitId":"P6A-U04","grade":6,"term":"A","unitNumber":4,"unitLesson":1,"order":13,"title":"线索藏在背景里","subtitle":"听读找线索，分类、改句子，再表达","minutes":12,"releaseId":"action-courses-v1","unitTitle":"好故事有线索","cards":[{"title":"线索藏在背景里","rule":"叙事中要分清过去正在进行的背景、发生的完整事件，以及同时进行的动作。阅读时把时间、原因与结果放回原文找依据，不把一种连词机械对应唯一时态。","example":"While the guide was studying a map, Eva was checking a compass.","translation":"向导研究地图时，Eva正在检查指南针。"},{"title":"线索藏在背景里","rule":"叙事中要分清过去正在进行的背景、发生的完整事件，以及同时进行的动作。阅读时把时间、原因与结果放回原文找依据，不把一种连词机械对应唯一时态。","example":"The gate creaked while the visitors were waiting.","translation":"访客等待时，大门吱呀作响。"},{"title":"线索藏在背景里","rule":"叙事中要分清过去正在进行的背景、发生的完整事件，以及同时进行的动作。阅读时把时间、原因与结果放回原文找依据，不把一种连词机械对应唯一时态。","example":"Eva was tracing a route when the curator called her.","translation":"馆员叫Eva时，她正在描路线。"}],"vocabulary":[{"word":"caretaker","meaning":"管理员"},{"word":"curator","meaning":"馆员"},{"word":"label","meaning":"标签"},{"word":"evidence","meaning":"依据"}],"task":"听读找依据，再分类、改一处句子、填词和拼句。是受控练习，不代替自由口语或写作。","topicIds":["tense.past-contrast","reading.inference"],"itemCount":9}');
